) AS (
  VALUES 
    (186::BIGINT, 'El lujo de tener un profesor qué tenga la intención de impartir deportes diferentes e inspirar a que los demás se atrevan y participen es algo que se nota gracias a su pasión por los deportes. Siempre te vas a sentir incluid@ y ve con toda la disposición de divertirse y aprender y se hace ameno.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2026-02-20T00:00:00+00:00'::TIMESTAMPTZ, '79f39fa6c381d93f5e19f6a78971549f466d7b3a2c261e53aa3dc4befb72d698'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'El profe es buena gente y flexible si usted tiene alguna situación, califica suave siempre y cuando usted participe, está dispuesto a ayudar, se pasa vacilón y se desestresa un rato, aveces es un poquillo exigente pero el asistente es muy calmado y buena nota.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2025-11-20T00:00:00+00:00'::TIMESTAMPTZ, '163c5237d5de7328a2eeea1bdca56798d961d1f6eae6e08d6fa007e67f504a8a'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Buen profe, le gusta la participación de los estudiantes en clase. Da porcentaje por actividades fuera de clase (como asistir a talleres de beis o de algún otro grupo)'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2025-07-28T00:00:00+00:00'::TIMESTAMPTZ, '9294e01efd765664b7c76a0bfe9e943cf29f65e3d14fd6169769fc125e2197da'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Conoce todo sobre este deporte, es buen profe solo que a veces puede ser muy grosero para hablar. Con el asistente es distinto, más calmado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '9877252b38e2149d35df3852e0d512cefed2471e84ec495e77910a52fef711e3'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Excelente profe, es relajado y muy tranquilo. Ayuda bastante y se esfuerza por enseñar el deporte.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2023-07-28T00:00:00+00:00'::TIMESTAMPTZ, '93b186b740d013e3eb6ddd40324c90f75f516845703243041d085c49d0d1d335'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'En general, me encantó la deportiva, fue muy entretenida y se aprende bastante. Solo tome en cuenta que debe ir a las clases, haga las coevaluaciones y listo, disfrute la clase, eso es lo que importa.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'ebff02b5bcb82ffb54a65fdcc2d1429e6dbdc1967d9384022273c2b141242035'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Asumió que todos sabíamos jugar baloncesto o estado en un equipo y se saltó las explicaciones de lo más básico. Los ejercicios en clase son muy confusos. Los que evalúan son los asistentes. Si va a clase y hace los portafolios, pasa. Si nunca ha tenido clases de baloncesto, no la recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'fc033a5ed9f5b20082ee002da7aaf88768ed1dfa03cf9e7bb647bf3ff1d65c8f'::TEXT, ARRAY[495]::BIGINT[]),
    (186::BIGINT, 'El profe es demasiado pura vida. El curso con él fue bastante sencillo y lo disfruté bastante. Es muy respetuoso y vacila bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, '4a24b15e3a22e3de204fcbb851a60e2fd071f901938855c8fd91800454d58137'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Si le cuadra el base, el profe esta muy bien, las clases se pasan rápido y literalmente solo se tiene preocupar de semana por medio para hacer el reporte de actividades que se monta en menos de 15 minutos. Muy fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '6f6d2ed368150463538a694c2202b0faab4a87359e1be9a7a5c0d8eda130b3ea'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Super sencillo pasar, si le gusta el base aprende y si no, pasa fácil. Buena gente y esforzado para dar las clases'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2021-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'd038ae17b2a64797ef3d90145ed42d3f2729d20e636188f6fa5c6304fd50c549'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Diay para ser un curso de 0 creditos este profe la da.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, 'fd7fa13d9368ee6f6ab5e6ab789b2fc20adfd0f987ecc08a7b6087ce76681aab'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Para pasar es requisito conectarse a todas las clases, y participar. Hay que enviar cada cierto tiempo evidencia con fotos suyas haciendo ejercicio. Es súper fácil pasar y es un curso muy básico, nada profundo'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, '52a05658ea979c0c7d4f1a8c0979e0070664588214aa29bce37deeee531e3137'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Si no quiere mandar fotos suyas haciendo feo, no matriculen con el'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '41ecb6ce4986f1a2631e96dfc29cb3038f178a8da993ffb3d49fc6581a9969c4'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'En virtual, realmente es muy sencillo aprobar el curso. Se debe conectar porque el si toma en cuenta la asistencia por lo tanto pasa lista Se expone en parejas algunas reglas o posiciones de juego y se lleva un portafolio de evidencias, donde se debe subir una foto o video de los ejercicios.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-12T00:00:00+00:00'::TIMESTAMPTZ, 'd1941850b9cef61a0b0cc9ab0617485b7b51625694141e3dd88f95977cf5fa45'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Si necesita llevar una deportiva, realmente llevar béisbol virtual fue una experiencia muy extraña pero el profe se esfuerza por explicar bien la materia con una presentación interactiva, la verdad el curso se pasa solo no es la gran cosa pero el si pasa lista, por lo que hay que conectarse a zoom.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '3adca2436f97d838b351a628d9ef431bca07920d27306aaac93e353c6d505df3'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Mae él nunca explicó nada, todo lo hacen los asistentes, es pésimo y no es muy bueno yo casi ni hacía ejercicio ahí no se hace nada, pésimo'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2019-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'd4a22b0f8f885bf9333f9c96d55550d522efaf3466b5dc87f62f91ed3d9c7fb1'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Perdimos muchas clases, pero la mayoría no fueron culpa del profe, las clases que tuvimos fueron entretenidas , pero el profe es a veces un poco bravo, pero en general es un buen profe, me hubiera gustado no perder tantas clases, volvería a llevar el curso con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, '572777b48edd4ac5bbad52e233c436b940f30d9ad014061949cb27e33ea5d78a'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'El curso es bonito y es super facil y basico, solo que el profe aveces es un poco bravo pero en general no molesta mucho'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2019-06-11T00:00:00+00:00'::TIMESTAMPTZ, '38f3773bf13469c3f28577b55b46dc74ce96c6f86a9fd24d5c5cefebc42ae257'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Ni siquiera es él el que imparte la clase. Super aburrida, no vuelvo a matricular ninguna deportiva por esto.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-05T00:00:00+00:00'::TIMESTAMPTZ, '92a839302f2600b44c45932907bb84b5041826fc43fc5cf02e154a0c70440239'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Es un profe de lo más tuanis, se aprende bastante del baseball con él, lo trata bien a uno, no lo obliga a llegar a los partidos y lo pone a practicar por posiciones con forme avanza el semestre. Si tienen que llevar una deportiva y no están seguros, con Miguel no se arrepentirán'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-10-28T00:00:00+00:00'::TIMESTAMPTZ, 'a5640f6ad1b9fb9a6ed5a3f3f4b2619d632e09be9c8a574ec894fe6da234795a'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Clases entretenidas y es evidente que el profesor realmente tiene pasión por lo que hace y se esfuerza en que la clase realmente aprenda del deporte.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2018-07-16T00:00:00+00:00'::TIMESTAMPTZ, '137fcc2bd1517cf5284568e23f385023b41c5474ea2e7eae2149a1934183ad00'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Las clases van bien si llega de buen humor, algo que no ocurre con tanta frecuencia; sino, es muy concho. No sabe bien las reglas del deporte. Frecuentemente se olvida que los estudiantes que llevamos esa electiva, a veces, no tenemos conocimientos previos sobre el tema.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '419684f4179f1c8d9f8dcb99cf3185883eb819020ce8ef5028177a26340dec99'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Es un buen profe. Es bastante comprensivo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-04T00:00:00+00:00'::TIMESTAMPTZ, '1087f8d3264f3c7275586e49b01911a513e00acf47b8939468435fe3380cef1b'::TEXT, ARRAY[492]::BIGINT[]),
    (186::BIGINT, 'Muy buen profe. Muy técnico, hace falta mas mejengas, pero es muy evidente que le importa que el estudiante aprenda de la disciplina.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'ccda02d36e9ab94d0e8608a670c38b61d382e85c70df41c6ec08a314bba09a80'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'La clase es entretenida y el profe súper cordial con el estudiante, recomendado'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-24T00:00:00+00:00'::TIMESTAMPTZ, '5c71da2018cc1c047274caae9bd2b06d1d8454d6d58b09aca4f8ddff8c3a4c9d'::TEXT, ARRAY[495]::BIGINT[]),
    (186::BIGINT, 'La verdad es que el curso es bastante suave, asi que no hay de que preocuparse, el es muy comprensivo y trata de ayudar cuando uno hace algo mal, es bastante amable!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'b009e79dc3d2ac5c5a824e3372dc35af27adc120c838838eab7452e7524dffa9'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Al principio no me gustaba mucho beis, porque apesto en eso. Sin embargo, las clases poco a poco se volvieron entretenidas. El profe muy buena nota. Entiende situaciones que se pueden presentar. Lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '0b560cf8545c9ed5bc0ee6e1de40cc5f968cae3ca06e629b7f21fe1a2e85d6b4'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Exelente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'ba55a92704ad7094923a6ed6014ac8c56f6bb3f7ce3cd032308879bf1b871fc1'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Buen profe, es vacilón, la clase es entretenida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '671b4d27aa4dd4dc5108b7c46b8fde0bb9d2c430f1cb748b3a2b21545d32408e'::TEXT, ARRAY[495]::BIGINT[]),
    (186::BIGINT, 'Es súper buena gente, fácil, si sos mujer y andas con la menstruación el lo entiende y no te obliga a reponer o a nadar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'bff2911b3fc348dc8ca31e72a1bea13c87660feee7edeb4fae702556dbd09126'::TEXT, ARRAY[492]::BIGINT[]),
    (186::BIGINT, '¡Muy buen profe! Las clases son muy chivas, se aprende mucho y ayudan a desestresarse del semestre.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'c39d8eff95e02928b882937978d1e3e6d07b0e26679950a492d1645e4f9aab4b'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Es muy buena persona, además ayuda si uno tiene algun tipo de enfermedad. Me parecio muy bueno, y lo mejor esta guapillo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2016-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'fe59cbc287bfe8d3bdfd38179a1fcfe9f50456743767b1ea4c34109d35ba7d9a'::TEXT, ARRAY[492]::BIGINT[]),
    (186::BIGINT, 'Es buena gente y no es estricto. Las clases son divertidas y ayudan a relajarse.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'd76c581495d545a392a153fcee5672a44840aba4d55bb35e3008d64c799e9f0c'::TEXT, ARRAY[492]::BIGINT[]),
    (186::BIGINT, 'Exelente curso, el profe es super tuanis, los juegos de beis y soft son muy divertidos y desestresante. 100% recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-02T00:00:00+00:00'::TIMESTAMPTZ, '9747c23229fe14cf54d82c7b10c24e2eee8016b825456ce722f75c383e6d4e79'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Clases divertidas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'ed736c8c865923ce08ff882e1f6437172ab0a7ba6e1ce63826b815d9675f0e9c'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Sus clases son muy entretenidas y quitan el estrés de la semana, es muy buena gente cuando entra en confianza y además no exige mucho. En general lo recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-20T00:00:00+00:00'::TIMESTAMPTZ, '9ec8e5350ae74c95306f9209dea987872194fa05c71d13c1b1fbee178c64dee1'::TEXT, ARRAY[492]::BIGINT[]),
    (186::BIGINT, 'El profe es serio, pero el curso muy entretenido, fácil de pasar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'fe83d668e54d66090308f14ca50d73057b23092fb353679d4268f8523d297ba4'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Solo hay que ir a clase y ya :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, 'e7d9c29bfdaa9672246fab3bbe7830461b2db61de12a99221be3860fd8e82105'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Él sabe que el curso es de relajarse y no pide mucho. Solo el que le interesa y pregunta recibe ayuda en técnicas o aprende reglas. Solo no olviden firmar la lista o la presentación del día de lluvia.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'a71d702ceb77f3391dae4db64aaed3e0da4699f04760b2320fc91d729a6c632a'::TEXT, ARRAY[578]::BIGINT[]),
    (186::BIGINT, 'Yo odio hacer deporte y con el mae no me disgusto tanto, es algo relajado pero tampoco confiarse'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'f6c30d18d0be645565ae7d7525b240fa497eb06fa2aed3c692a2c24191ff0e9d'::TEXT, ARRAY[578]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
